std::vector<int> prefix(const std::vector<int>& a) {
    std::vector<int> P(a.size() + 1, 0);
    for (size_t i = 0; i < a.size(); i++)
        P[i + 1] = P[i] + a[i];
    return P;
}

long long divisible(const std::vector<int>& a, int k) {
    std::vector<long long> cnt(k, 0);
    cnt[0] = 1;
    long long s = 0, res = 0;
    for (int x : a) {
        s += x;
        int m = s % k;
        res += cnt[m];
        cnt[m]++;
    }
    return res;
}

